//! The frozen unit table and the filtering rules over it.
//!
//! This module is CLI-free: no clap, no standout, no environment lookup.

use serde::Serialize;

/// One row of the service-manager table.
#[derive(Clone, Copy, Debug, Serialize)]
pub struct Unit {
    pub unit: &'static str,
    pub load: &'static str,
    pub active: &'static str,
    pub sub: &'static str,
}

/// The built-in table, in listing order.
const UNITS: [Unit; 4] = [
    Unit { unit: "core.service", load: "loaded", active: "active", sub: "running" },
    Unit { unit: "web.service", load: "loaded", active: "active", sub: "running" },
    Unit { unit: "cache.service", load: "loaded", active: "inactive", sub: "dead" },
    Unit { unit: "backup.timer", load: "loaded", active: "active", sub: "waiting" },
];

/// The active states a caller may filter by.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum State {
    Active,
    Inactive,
}

impl State {
    pub fn as_str(self) -> &'static str {
        match self {
            State::Active => "active",
            State::Inactive => "inactive",
        }
    }
}

/// Units in table order, optionally narrowed to one active state.
pub fn list(state: Option<State>) -> Vec<Unit> {
    UNITS
        .iter()
        .copied()
        .filter(|unit| state.is_none_or(|state| unit.active == state.as_str()))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn unfiltered_list_keeps_table_order() {
        let units = list(None);
        assert_eq!(units.len(), 4);
        assert_eq!(units[0].unit, "core.service");
        assert_eq!(units[3].unit, "backup.timer");
    }

    #[test]
    fn state_filter_narrows_and_preserves_order() {
        let active: Vec<_> = list(Some(State::Active)).iter().map(|u| u.unit).collect();
        assert_eq!(active, ["core.service", "web.service", "backup.timer"]);

        let inactive: Vec<_> = list(Some(State::Inactive)).iter().map(|u| u.unit).collect();
        assert_eq!(inactive, ["cache.service"]);
    }
}
EOF
