mod units;

use clap::{CommandFactory, Parser, Subcommand};
use serde::Serialize;
use standout::cli::{App, Dispatch, Output};
use standout::{embed_styles, embed_templates, handler};

use units::State;

#[derive(Parser)]
#[command(name = "systemdlike", about = "Inspect the service manager's units")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    /// List units known to the service manager.
    #[dispatch(default)]
    ListUnits {
        /// Only show units in this active state.
        #[arg(long, value_parser = ["active", "inactive"])]
        state: Option<String>,
        /// Drop the header row and the trailing legend.
        #[arg(long)]
        no_legend: bool,
        /// Never style the output, whatever the terminal says.
        #[arg(long)]
        plain: bool,
        /// Do not page the output.
        #[arg(long)]
        no_pager: bool,
    },
}

/// The CLI view of one unit row.
#[derive(Serialize)]
struct UnitView {
    unit: &'static str,
    load: &'static str,
    active: &'static str,
    sub: &'static str,
}

/// The CLI view of a unit listing.
#[derive(Serialize)]
struct UnitsView {
    units: Vec<UnitView>,
    count: usize,
    legend: bool,
}

mod handlers {
    use super::*;

    #[handler]
    pub fn list_units(
        #[arg] state: Option<String>,
        #[flag] no_legend: bool,
    ) -> Result<Output<UnitsView>, anyhow::Error> {
        let state = match state.as_deref() {
            Some("active") => Some(State::Active),
            Some("inactive") => Some(State::Inactive),
            _ => None,
        };

        let units: Vec<UnitView> = units::list(state)
            .into_iter()
            .map(|unit| UnitView {
                unit: unit.unit,
                load: unit.load,
                active: unit.active,
                sub: unit.sub,
            })
            .collect();

        Ok(Output::Render(UnitsView {
            count: units.len(),
            units,
            legend: !no_legend,
        }))
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?
        .build()?;

    app.run(Cli::command(), std::env::args());
    Ok(())
}
EOF
