//! The color discipline: which `--output` mode an invocation should run under.

/// The modes that mean "render the template"; only these carry ANSI styling.
const TEMPLATED: [&str; 4] = ["auto", "term", "text", "term-debug"];

/// Returns the argument list to run with, appending an `--output` mode when
/// this application — not the terminal — owns the color decision.
///
/// First rule that applies wins:
/// 1. `--plain`, or an explicit `--output` mode.
/// 2. `SYSTEMDLIKE_COLORS`: `1` forces ANSI, `0` forces plain.
/// 3. `NO_COLOR` set to anything: plain.
/// 4. Autodetection, which is the framework's `auto` default.
pub fn args_with_output_mode(argv: &[String]) -> Vec<String> {
    let explicit = explicit_output_mode(argv);
    let structured = explicit
        .as_deref()
        .is_some_and(|mode| !TEMPLATED.contains(&mode));

    let forced = if structured {
        // `--plain` says nothing about JSON, YAML, XML or CSV.
        None
    } else if has_flag(argv, "--plain") {
        Some("text")
    } else if explicit.is_some() {
        None
    } else {
        match std::env::var("SYSTEMDLIKE_COLORS").as_deref() {
            Ok("1") => Some("term"),
            Ok("0") => Some("text"),
            _ if std::env::var_os("NO_COLOR").is_some() => Some("text"),
            _ => None,
        }
    };

    let mut args = argv.to_vec();
    if let Some(mode) = forced {
        args.push(format!("--output={mode}"));
    }
    args
}

/// The value of an explicitly passed `--output`, in either spelling.
fn explicit_output_mode(argv: &[String]) -> Option<String> {
    let mut args = argv.iter();
    while let Some(arg) = args.next() {
        if let Some(value) = arg.strip_prefix("--output=") {
            return Some(value.to_string());
        }
        if arg == "--output" {
            return args.next().cloned();
        }
    }
    None
}

pub fn has_flag(argv: &[String], flag: &str) -> bool {
    argv.iter().any(|arg| arg == flag)
}
EOF
