//! The pager discipline: list output pages on an attended terminal.

use std::io::Write;
use std::process::{Command, Stdio};

use crate::styling::has_flag;

pub struct Pager {
    command: String,
}

/// The pager for this invocation, or `None` when the output must not be paged.
///
/// Paging needs an attended terminal, no `--no-pager`, and a pager command from
/// `SYSTEMDLIKE_PAGER`, else `PAGER`.
pub fn selected(argv: &[String], stdout_is_terminal: bool) -> Option<Pager> {
    if !stdout_is_terminal || has_flag(argv, "--no-pager") {
        return None;
    }

    let command = match std::env::var("SYSTEMDLIKE_PAGER") {
        Ok(command) => command,
        Err(_) => std::env::var("PAGER").ok()?,
    };

    (!command.trim().is_empty()).then_some(Pager { command })
}

impl Pager {
    /// Feeds `text` to the pager, waiting for the reader to finish.
    pub fn page(&self, text: &str) -> std::io::Result<()> {
        let mut child = Command::new("sh")
            .arg("-c")
            .arg(&self.command)
            .stdin(Stdio::piped())
            .spawn()?;

        if let Some(stdin) = child.stdin.as_mut() {
            let ignore_broken_pipe = |result: std::io::Result<()>| match result {
                Err(error) if error.kind() == std::io::ErrorKind::BrokenPipe => Ok(()),
                other => other,
            };
            ignore_broken_pipe(stdin.write_all(text.as_bytes()))?;
            if !text.ends_with('\n') {
                ignore_broken_pipe(stdin.write_all(b"\n"))?;
            }
        }
        drop(child.stdin.take());

        child.wait()?;
        Ok(())
    }
}
EOF
