//! The color discipline: whether an invocation renders styled or plain.

/// The modes that render the template; only these carry ANSI styling.
const TEMPLATED: [&str; 4] = ["auto", "term", "text", "term-debug"];

/// What this application decided about styling, when it decided at all.
enum Styling {
    /// ANSI, whatever the terminal is.
    Ansi,
    /// Undecorated, whatever the terminal is.
    Plain,
    /// Nothing to say: the framework autodetects.
    Autodetect,
}

/// Returns the argument list to run with, appending the `--output` mode that
/// carries this application's color decision to the framework.
///
/// First rule that applies wins:
/// 1. `--plain`, or an explicit `--output` mode.
/// 2. `SYSTEMDLIKE_COLORS`: `1` forces ANSI, `0` forces plain.
/// 3. `NO_COLOR` set to anything: plain.
/// 4. Autodetection: ANSI on a color-capable attended terminal, plain otherwise.
pub fn args_with_output_mode(argv: &[String]) -> Vec<String> {
    let mut args = argv.to_vec();

    match decide(argv) {
        Styling::Ansi => {
            // `--output=term` asks for ANSI; the terminal abstraction underneath
            // still suppresses codes on a pipe unless told to force them.
            std::env::set_var("CLICOLOR_FORCE", "1");
            args.push("--output=term".to_string());
        }
        Styling::Plain => args.push("--output=text".to_string()),
        Styling::Autodetect => {}
    }

    args
}

fn decide(argv: &[String]) -> Styling {
    let explicit = explicit_output_mode(argv);

    // Structured modes (json, yaml, xml, csv) have no styling to decide.
    if explicit
        .as_deref()
        .is_some_and(|mode| !TEMPLATED.contains(&mode))
    {
        return Styling::Autodetect;
    }

    if has_flag(argv, "--plain") {
        return Styling::Plain;
    }
    if explicit.is_some() {
        return Styling::Autodetect;
    }

    match std::env::var("SYSTEMDLIKE_COLORS").as_deref() {
        Ok("1") => Styling::Ansi,
        Ok("0") => Styling::Plain,
        _ if std::env::var_os("NO_COLOR").is_some() => Styling::Plain,
        _ => Styling::Autodetect,
    }
}

/// The value of an explicitly passed `--output`, in either spelling.
fn explicit_output_mode(argv: &[String]) -> Option<String> {
    let mut args = argv.iter();
    while let Some(arg) = args.next() {
        if let Some(value) = arg.strip_prefix("--output=") {
            return Some(value.to_string());
        }
        if arg == "--output" {
            return args.next().cloned();
        }
    }
    None
}

pub fn has_flag(argv: &[String], flag: &str) -> bool {
    argv.iter().any(|arg| arg == flag)
}
