 25	    ListUnits {
 26	        /// Only show units in this active state.
 27	        #[arg(long, value_parser = ["active", "inactive"])]
 28	        state: Option<String>,
 29	        /// Drop the header row and the trailing legend.
 30	        #[arg(long)]
 31	        no_legend: bool,
 32	        /// Never style the output, whatever the terminal says.
 33	        #[arg(long)]
