 43	pub struct UnitView {
 44	    pub unit: &'static str,
 45	    pub load: &'static str,
 46	    pub active: &'static str,
 47	    pub sub: &'static str,
 48	}
 49	
 50	/// The CLI view of a unit listing.
 51	#[derive(Serialize)]
 52	pub struct UnitsView {
 53	    pub units: Vec<UnitView>,
 54	    pub count: usize,
 55	    pub legend: bool,
 56	}
 57	
 58	#[allow(non_snake_case)]
 59	mod handlers {
 60	    use super::*;
 61	
 62	    #[handler]
 63	    pub fn list_units(
 64	        #[arg] state: Option<String>,
 65	        #[flag(name = "no_legend")] no_legend: bool,
 66	    ) -> Result<Output<UnitsView>, anyhow::Error> {
 67	        let state = match state.as_deref() {
 68	            Some("active") => Some(State::Active),
 69	            Some("inactive") => Some(State::Inactive),
 70	            _ => None,
 71	        };
 72	
 73	        let units: Vec<UnitView> = units::list(state)
 74	            .into_iter()
 75	            .map(|unit| UnitView {
 76	                unit: unit.unit,
 77	                load: unit.load,
 78	                active: unit.active,
 79	                sub: unit.sub,
 80	            })
 81	            .collect();
 82	
 83	        Ok(Output::Render(UnitsView {
 84	            count: units.len(),
 85	            units,
 86	            legend: !no_legend,
 87	        }))
 88	    }
 89	}
 90	
 91	fn main() -> Result<ExitCode, Box<dyn std::error::Error>> {
 92	    let argv: Vec<String> = std::env::args().collect();
 93	
 94	    let app = App::builder()
 95	        .templates(embed_templates!("src/templates"))
 96	        .styles(embed_styles!("src/styles"))
 97	        .default_theme("default")
 98	        .default_command("list-units")
 99	        .command_with("list-units", handlers::list_units__handler, |config| {
100	            config.template("list-units")
101	        })?
102	        .build()?;
103	
104	    // The color decision is ours (SYSTEMDLIKE_COLORS / NO_COLOR / --plain);
105	    // it is handed to the framework as the `--output` mode it already owns.
106	    let args = styling::args_with_output_mode(&argv);
107	
108	    let pager = pager::selected(&argv, std::io::stdout().is_terminal());
109	    let Some(pager) = pager else {
110	        app.run(Cli::command(), args);
111	        return Ok(ExitCode::SUCCESS);
112	    };
113	
114	    // Paging needs the text in hand, so capture instead of letting `run` write.
115	    Ok(match app.run_to_string(Cli::command(), args) {
116	        RunResult::Handled(output) => {
117	            pager.page(output.as_str())?;
118	            ExitCode::SUCCESS
119	        }
120	        RunResult::Error(error) => {
121	            eprintln!("{}", error);
122	            ExitCode::from(error.exit_status().code())
123	        }
124	        _ => ExitCode::SUCCESS,
125	    })
126	}

